CREATE FUNCTION public.manage_provider_catalog_schedule() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _job bigint; _cfg public.provider_sync_settings; _command text; BEGIN SELECT jobid INTO _job FROM cron.job WHERE jobname='provider-catalog-'||NEW.id::text; IF _job IS NOT NULL THEN PERFORM cron.unschedule(_job); END IF; IF NEW.active AND NEW.deleted_at IS NULL THEN SELECT * INTO _cfg FROM public.provider_sync_settings WHERE id=1; IF FOUND THEN _command:=format('SELECT net.http_post(url:=%L, headers:=%L::jsonb, body:=%L::jsonb, timeout_milliseconds:=60000)',_cfg.callback_url,jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||_cfg.callback_secret)::text,jsonb_build_object('id',NEW.id)::text); PERFORM cron.schedule('provider-catalog-'||NEW.id::text,'17 * * * *',_command); END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.manage_provider_catalog_schedule() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER provider_catalog_schedule AFTER INSERT OR UPDATE OF active,deleted_at ON public.service_providers FOR EACH ROW EXECUTE FUNCTION public.manage_provider_catalog_schedule();